import Splide from "@splidejs/splide";
import Component from "@js/core/component";

class SliderUi extends Component {
  #mainSettings = null
  #mainConfig = null

  #navigationSettings = null
  #navigationConfig = null

  #hasNavigation = false
  #hasModal = false

  static mainConfig = {
    type: 'slide',
    rewind: false,
    start: 0,
    perPage: 1,
    perMove: 1,
    gap: 20,
    drag: 'free',
    snap: true,
    arrows: false,
    pagination: false,
    autoplay: false,
    interval: 5000,
    speed: 1000,
    pauseOnHover: false,
    pauseOnFocus: false,
    keyboard: true,
    trimSpace: true,
    updateOnMove: true,
    mediaQuery: 'min',
  }

  static navigationConfig = {
    type: 'slide',
    start: 0,
    perPage: 4,
    perMove: 1,
    gap: 20,
    drag: 'free',
    snap: true,
    arrows: false,
    pagination: false,
    isNavigation: true,
    mediaQuery: 'min',
  }

  static modalConfig = {
    mediaQuery: 'min',
  }

  constructor() {
    super()
    this.requiredRefs = ['mainSliderUi', 'mainSliderTrack', 'mainSliderList']
    this.mainSplide = null
    this.navigationSplide = null
    this.modalSplide = null
  }

  connectedCallback() {
    super.connectedCallback()
    this.#buildMainConfig()

    this.mainSplide = new Splide(this.refs.mainSliderUi, this.#mainConfig)

    this.#buildNavigationSlider()
    this.#buildModalSlider()

    this.mainSplide.mount()
  }

  disconnectedCallback() {}

  #buildMainConfig() {
    this.#mainSettings = this.#parseConfig(this.refs.mainSliderConfig)

    if (!Object.entries(this.#mainSettings).size) {
      this.#mainConfig = SliderUi.mainConfig
      return
    }

    const { type, loop, enable_controls_lg, arrows_sm, arrows_lg, pagination_sm, pagination_lg } = this.#mainSettings

    const parsedType = type === 'fade'
      ? type
      : type === 'slide' && loop === true
        ? 'loop'
        : type

    const config = {
      type: parsedType,
      rewind: type === 'fade' && loop === true,
      autoplay: this.#mainSettings.autoplay,
      interval: this.#mainSettings.interval,
      speed: this.#mainSettings.speed,
      arrows: arrows_sm === 'show',
      pagination: pagination_sm === 'show',
      ...(type === 'fade' && {
        perPage: null,
        perMove: null,
        drag: true,
        snap: false,
      }),
      ...(enable_controls_lg && {
        breakpoints: {
          1024: {
            arrows: arrows_lg === 'show',
            pagination: pagination_sm === 'show',
          },
        },
      }),
    }

    this.#mainConfig = {
      ...SliderUi.mainConfig,
      ...config,
    }
  }

  #buildNavigationSlider() {
    if (!('navigationSliderUi' in this.refs)) return

    this.#navigationSettings = this.#parseConfig(this.refs.navigationSliderConfig)

    if (!Object.entries(this.#navigationSettings).size) {
      this.#navigationConfig = SliderUi.navigationConfig
      this.navigationSplide = new Splide()
      return
    }
  }

  #buildModalSlider() {
    if (!('modalSliderUi' in this.refs)) return
    console.log('HEY! THIS HAS A MODAL SLIDER!')
  }

  #parseConfig(ref) {
    const text = ref?.textContent?.trim()
    return text
      ? JSON.parse(text)
      : {}
  }
}

export default SliderUi